24	  fn decode_with_jwk(&self, token: &str, jwk: &Jwk) -> Result<JwtClaim, Error> {
25	    let key = DecodingKey::from_jwk(jwk).map_err(|_| Error::ValidationCheckFailed)?;
26	    let algorithm = jwk
27	      .common
28	      .key_algorithm
29	      .and_then(|alg| Algorithm::from_str(alg.to_string().as_str()).ok())
30	      .ok_or(Error::ValidationCheckFailed)?;
31	    let mut validation = Validation::new(algorithm);
32	
33	    // will validate on our side later
34	    validation.validate_aud = false;
35	
36	    let decoded = decode::<JwtClaim>(token, &key, &validation).map_err(|_| Error::Invalid)?;
37	
38	    Ok(decoded.claims)
39	  }
40	
41	  pub fn decode(&self, token: &str) -> Result<JwtClaim, Error> {
42	    let header = decode_header(token).map_err(|_| Error::Invalid)?;
43	
44	    if let Some(kid) = &header.kid {
45	      let jwk = self.set.find(kid).ok_or(Error::ValidationCheckFailed)?;
46	
47	      self.decode_with_jwk(token, jwk)
48	    } else {
49	      if !self.optional_kid {
50	        return Err(Error::Invalid);
51	      }
52	
53	      // iterate over all available jwk and try to decode incoming token with it
54	      // if any succeeds return the data
55	      for jwk in self.set.keys.iter() {
56	        if let Ok(claims) = self.decode_with_jwk(token, jwk) {
57	          return Ok(claims);
58	        }
59	      }
60	
61	      Err(Error::Invalid)
62	    }
63	  }
64	}
