31	  pub fn new(url: Url, client: Arc<dyn HttpIO>, max_age: Duration) -> Self {
32	    Self { url, client, max_age, cache: RwLock::new(None), optional_kid: false }
33	  }
34	
35	  /// If called with `true`, subsequent `decode` calls will
36	  /// try all keys from the key set if a `kid` is not specified in the token.
37	  pub fn optional_kid(mut self, optional: bool) -> Self {
38	    self.optional_kid = optional;
39	
40	    self
41	  }
