43	  pub async fn decode(&self, token: &str) -> Result<JwtClaim, Error> {
44	    {
45	      let cache = self.cache.read().unwrap();
46	
47	      if let Some(c) = cache.as_ref() {
48	        if c.expiration > Instant::now() {
49	          return c.jwks.decode(token);
50	        }
51	      }
52	    }
53	
54	    let jwks = self.request_jwks().await.map_err(|_| Error::ValidationCheckFailed)?;
55	
56	    let mut cache = self.cache.write().unwrap();
57	    if let Some(c) = cache.as_ref() {
58	      if c.expiration > Instant::now() {
59	        return c.jwks.decode(token);
60	      }
61	    }
62	
63	    *cache = Some(JwksCache {
64	      jwks: {
65	        let v = Jwks::from(jwks);
66	        v.optional_kid(self.optional_kid)
67	      },
68	      expiration: std::time::Instant::now() + self.max_age,
69	    });
70	
71	    cache.as_ref().unwrap().jwks.decode(token).map_err(|_| Error::Invalid)
72	  }
73	
74	  async fn request_jwks(&self) -> anyhow::Result<JwkSet> {
75	    let mut request = Request::new(Method::GET, self.url.clone());
76	
77	    request
78	      .headers_mut()
79	      .insert("accept", HeaderValue::from_static(mime::APPLICATION_JSON.as_ref()));
80	
81	    let response = self.client.execute(request).await?;
82	    Ok(response.to_json()?.body)
83	  }
84	}
