36	  fn resolve_token(&self, request: &RequestContext) -> Option<String> {
37	    let value = request.req_headers.typed_get::<Authorization<Bearer>>();
38	
39	    value.map(|token| token.token().to_owned())
40	  }
41	
42	  async fn validate_token(&self, token: &str) -> Result<(), Error> {
43	    let claims = self
44	      .decoder
45	      .decode(token)
46	      .await
47	      .map_err(|_| Error::ValidationCheckFailed)?;
48	
49	    self.validate_claims(&claims)
50	  }
51	
52	  fn validate_claims(&self, claims: &JwtClaim) -> Result<(), Error> {
53	    if !validate_iss(&self.options, claims) || !validate_aud(&self.options, claims) {
54	      return Err(Error::Invalid);
55	    }
56	
57	    Ok(())
58	  }
59	}
