61	impl Verify for JwtVerifier {
62	  async fn verify(&self, request: &RequestContext) -> Result<(), Error> {
63	    let token = self.resolve_token(request);
64	
65	    let Some(token) = token else {
66	      return Err(Error::Missing);
67	    };
68	
69	    self.validate_token(&token).await
70	  }
71	}
