73	pub fn validate_iss(options: &blueprint::JwtProvider, claims: &JwtClaim) -> bool {
74	  options
75	    .issuer
76	    .as_ref()
77	    .map(|issuer| claims.iss.as_ref().map(|iss| iss == issuer).unwrap_or(false))
78	    .unwrap_or(true)
79	}
80	
81	pub fn validate_aud(options: &blueprint::JwtProvider, claims: &JwtClaim) -> bool {
82	  let audiences = &options.audiences;
83	
84	  if audiences.is_empty() {
85	    true
86	  } else {
87	    let Some(aud) = &claims.aud else { return false };
88	
89	    match aud {
90	      OneOrMany::One(aud) => audiences.contains(aud),
91	      // if user token has list of aud, validate that at least one of them is inside validation set
92	      OneOrMany::Vec(auds) => auds.iter().any(|aud| audiences.contains(aud)),
93	    }
94	  }
95	}
